(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-376":{scenario:{legacy:"D"},learning:{summary:{vi:"Chuyên viên Quảng cáo hiệu suất đa kênh lập kế hoạch, triển khai và tối ưu chiến dịch quảng cáo trả phí trên công cụ tìm kiếm, mạng xã hội và nền tảng video ngắn để đạt mục tiêu chuyển đổi đo được (đơn hàng, khách hàng tiềm năng, lượt cài đặt) với chi phí hợp lý. Nghề đòi hỏi đo lường chính xác, tư duy thử nghiệm, phân bổ ngân sách theo hiệu quả thật và tuân thủ quy định quảng cáo, dữ liệu cá nhân.",en:"A Performance Marketing Specialist plans, launches and optimizes paid campaigns across search, social and short-video platforms to reach measurable conversion goals (orders, leads, installs) at an efficient cost. The role requires accurate measurement, an experimentation mindset, budget allocation by true efficiency and compliance with advertising and personal data rules."},responsibilities:{vi:["Lập kế hoạch kênh, ngân sách và mục tiêu CPA, ROAS theo từng giai đoạn của phễu chuyển đổi.","Thiết lập cấu trúc chiến dịch, nhóm quảng cáo, đối tượng và chiến lược đặt giá thầu.","Cài đặt và kiểm tra đo lường: pixel, API chuyển đổi phía máy chủ, UTM, sự kiện chuyển đổi.","Thử nghiệm A/B mẫu quảng cáo, trang đích và đối tượng; tối ưu hằng ngày theo dữ liệu.","Báo cáo hiệu quả, phân bổ lại ngân sách giữa các kênh và đề xuất kiểm định tăng trưởng thực."],en:["Plan channels, budgets and CPA and ROAS targets for each stage of the conversion funnel.","Set up campaign structure, ad groups, audiences and bidding strategies.","Implement and audit measurement: pixels, server-side conversion APIs, UTMs and conversion events.","A/B test creatives, landing pages and audiences; optimize daily from data.","Report performance, reallocate budget across channels and propose incrementality tests."]},competencies:[{name:{vi:"Đo lường & phân bổ chuyển đổi",en:"Measurement & attribution"},desc:{vi:"Hiểu các mô hình phân bổ, giới hạn của dữ liệu nền tảng và cách kiểm chứng bằng nhóm đối chứng.",en:"Understand attribution models, the limits of platform data and validation with control groups."}},{name:{vi:"Tối ưu đấu giá & ngân sách",en:"Auction & budget optimization"},desc:{vi:"Chọn chiến lược giá thầu, điều chỉnh ngân sách theo hiệu quả biên thay vì hiệu quả trung bình.",en:"Choose bidding strategies and shift budget by marginal rather than average efficiency."}},{name:{vi:"Tư duy thử nghiệm",en:"Experimentation"},desc:{vi:"Đặt giả thuyết, thiết kế A/B đủ cỡ mẫu và chỉ kết luận khi có ý nghĩa thống kê.",en:"Form hypotheses, design properly sized A/B tests and conclude only on statistical significance."}},{name:{vi:"Phối hợp sáng tạo",en:"Creative collaboration"},desc:{vi:"Đưa dữ liệu vào brief sáng tạo, phát hiện mẫu quảng cáo mỏi và đề xuất góc tiếp cận mới.",en:"Feed data into creative briefs, spot creative fatigue and suggest new angles."}},{name:{vi:"Tuân thủ quảng cáo",en:"Advertising compliance"},desc:{vi:"Chỉ dùng thông điệp có bằng chứng, tôn trọng chính sách nền tảng và quyền riêng tư người dùng.",en:"Use only substantiated claims and respect platform policies and user privacy."}}],knowledge:{vi:["Chỉ số hiệu suất: CPM, CPC, CTR, CVR, CPA, ROAS, MER và giá trị vòng đời khách hàng.","Cơ chế đấu giá quảng cáo, điểm chất lượng, mức độ liên quan và các chiến lược giá thầu tự động.","Mô hình phân bổ (lượt nhấp cuối, theo dữ liệu), kiểm định tăng trưởng thực (lift test, holdout).","Luật Quảng cáo năm 2012 và các văn bản sửa đổi, hướng dẫn; chính sách quảng cáo của từng nền tảng.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân khi theo dõi chuyển đổi và tiếp thị lại."],en:["Performance metrics: CPM, CPC, CTR, CVR, CPA, ROAS, MER and customer lifetime value.","Ad auction mechanics, quality and relevance scores and automated bidding strategies.","Attribution models (last click, data-driven) and incrementality testing (lift tests, holdouts).","The 2012 Advertising Law with its amendments and guidance; each platform's advertising policies.","Decree 13/2023/ND-CP on personal data protection for conversion tracking and retargeting."]},tools:["Trình quản lý quảng cáo tìm kiếm","Trình quản lý quảng cáo mạng xã hội","Công cụ phân tích web (GA4)","Tag manager / server-side tracking","Looker Studio / BI","Microsoft Excel"],kpis:{vi:["CPA hoặc ROAS so với mục tiêu đã duyệt theo từng kênh.","Tỷ lệ chuyển đổi trang đích và tỷ lệ nhấp quảng cáo.","Mức tăng trưởng thực (incremental) đo bằng nhóm đối chứng.","Mức độ chính xác của dữ liệu chuyển đổi so với hệ thống đơn hàng."],en:["CPA or ROAS versus the approved target per channel.","Landing page conversion rate and ad click-through rate.","True incremental lift measured with control groups.","Accuracy of conversion data versus the order system."]},day:[{time:"08:30",vi:"Kiểm tra chi tiêu, CPA, ROAS hôm qua và cảnh báo bất thường trên các nền tảng.",en:"Check yesterday's spend, CPA, ROAS and anomaly alerts across platforms."},{time:"10:00",vi:"Đối chiếu số chuyển đổi nền tảng với hệ thống đơn hàng, sửa lỗi gắn thẻ.",en:"Reconcile platform conversions with the order system and fix tagging errors."},{time:"13:30",vi:"Thiết kế thử nghiệm A/B mẫu quảng cáo mới cùng đội sáng tạo.",en:"Design an A/B test for new creatives with the creative team."},{time:"15:30",vi:"Phân bổ lại ngân sách giữa tìm kiếm và mạng xã hội theo hiệu quả biên.",en:"Reallocate budget between search and social by marginal efficiency."},{time:"17:00",vi:"Gửi báo cáo ngày, ghi nhận bài học thử nghiệm và kế hoạch ngày mai.",en:"Send the daily report, log test learnings and tomorrow's plan."}],mistakes:{vi:["Tin hoàn toàn số chuyển đổi do nền tảng tự báo cáo mà không đối chiếu đơn hàng thật.","Kết luận thử nghiệm A/B quá sớm khi chưa đủ cỡ mẫu và ý nghĩa thống kê.","Dùng thông điệp cam kết tuyệt đối không có bằng chứng để tăng tỷ lệ chuyển đổi."],en:["Trusting platform-reported conversions without reconciling real orders.","Calling A/B tests too early before reaching sample size and significance.","Using absolute, unsubstantiated promises to lift conversion rates."]},career:[{vi:"Nhân viên vận hành quảng cáo",en:"Ads Operations Executive"},{vi:"Chuyên viên Quảng cáo hiệu suất",en:"Performance Marketing Specialist"},{vi:"Trưởng nhóm Performance Marketing",en:"Performance Marketing Lead"},{vi:"Giám đốc Marketing tăng trưởng / Digital",en:"Head of Growth / Digital Marketing Director"}],glossary:[{term:"CPA",vi:"Chi phí cho mỗi chuyển đổi, bằng tổng chi tiêu chia số chuyển đổi.",en:"Cost per acquisition, total spend divided by conversions."},{term:"ROAS",vi:"Doanh thu quảng cáo trên chi phí quảng cáo, đo hiệu quả hoàn vốn của ngân sách.",en:"Return on ad spend, ad-attributed revenue divided by ad cost."},{term:"Attribution",vi:"Quy tắc gán công lao chuyển đổi cho các điểm chạm quảng cáo trên hành trình khách hàng.",en:"Rules that assign conversion credit to ad touchpoints along the customer journey."},{term:"Lift test",vi:"Thử nghiệm so sánh nhóm thấy quảng cáo và nhóm đối chứng để đo tăng trưởng thực.",en:"A test comparing an exposed group with a control group to measure true incremental impact."},{term:"Creative fatigue",vi:"Hiện tượng mẫu quảng cáo giảm hiệu quả do tần suất hiển thị cao với cùng đối tượng.",en:"Declining ad performance caused by high frequency to the same audience."}],quiz:[{q:{vi:"Kênh A chi 4000 có 80 chuyển đổi, kênh B chi 6000 có 20 chuyển đổi. CPA của kênh A là bao nhiêu?",en:"Channel A spends 4000 for 80 conversions, channel B spends 6000 for 20. What is channel A's CPA?"},options:{vi:["300","100","50","200"],en:["300","100","50","200"]},answer:2,explain:{vi:"CPA = 4000 / 80 = 50; kênh B có CPA 300 nên kém hiệu quả hơn nhiều.",en:"CPA = 4000 / 80 = 50; channel B's CPA is 300, far less efficient."}},{q:{vi:"Cách tin cậy nhất để biết quảng cáo có tạo doanh số tăng thêm thật hay không?",en:"What is the most reliable way to know whether ads create true incremental sales?"},options:{vi:["Thử nghiệm có nhóm đối chứng (holdout)","Xem ROAS do nền tảng báo cáo","So sánh với tháng trước","Hỏi ý kiến đội bán hàng"],en:["A test with a holdout control group","Platform-reported ROAS","Comparing with last month","Asking the sales team"]},answer:0,explain:{vi:"Nhóm đối chứng loại trừ doanh số tự nhiên, cho thấy phần tăng thêm do quảng cáo tạo ra.",en:"A control group removes organic sales and reveals the increment caused by ads."}},{q:{vi:"Thử nghiệm A/B mới chạy 2 ngày, mẫu B đang cao hơn 15% nhưng chưa có ý nghĩa thống kê. Nên làm gì?",en:"An A/B test has run 2 days; variant B leads by 15% but is not significant. What should you do?"},options:{vi:["Dừng ngay và chọn B","Tăng gấp đôi ngân sách cho B","Xóa thử nghiệm và làm lại từ đầu","Chạy tiếp đến cỡ mẫu đã định rồi mới kết luận"],en:["Stop now and pick B","Double B's budget","Delete the test and restart","Run to the planned sample size before concluding"]},answer:3,explain:{vi:"Kết luận sớm dễ chọn nhầm do dao động ngẫu nhiên; phải đạt cỡ mẫu và ý nghĩa đã định trước.",en:"Early calls often pick noise; reach the pre-set sample size and significance first."}},{q:{vi:"Khách hàng yêu cầu quảng cáo ghi “hiệu quả đảm bảo 100%” dù không có bằng chứng. Bạn xử lý thế nào?",en:"The client wants ads to say “100% guaranteed results” with no evidence. How do you handle it?"},options:{vi:["Chạy thử vài ngày rồi gỡ","Từ chối, đề xuất thông điệp có bằng chứng và thử nghiệm A/B có đo lường","Chỉ chạy trên một nền tảng","Thêm dấu sao chú thích thật nhỏ"],en:["Run it a few days then remove it","Decline, propose substantiated messaging and a measured A/B test","Run it on one platform only","Add a tiny asterisk note"]},answer:1,explain:{vi:"Thông điệp không có căn cứ vi phạm quy định quảng cáo và chính sách nền tảng; dùng bằng chứng và kiểm chứng bằng thử nghiệm.",en:"Unsubstantiated claims breach advertising rules and platform policies; use evidence and validate by testing."}}],tools_en:["Search ads manager","Social media ads manager","Web analytics tool (GA4)","Tag manager / server-side tracking","Looker Studio / BI","Microsoft Excel"]}}})})(window.KKR);
